import { createContext, useContext, useState, ReactNode } from "react";

interface GlobalContextType {
  keysPressed: string; 
  setKeysPressed: (keys: string | ((prevKeys: string) => string)) => void; // Allow both string and function
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

interface GlobalProviderProps {
  children: ReactNode;
}

export const useGlobalContext = () => useContext(GlobalContext);

const AppContext: React.FC<GlobalProviderProps> = ({ children }) => {
    const [keysPressed, setKeysPressed] = useState<string>('B');

    return(
        <GlobalContext.Provider value = {{keysPressed, setKeysPressed}}>
            {children}
        </GlobalContext.Provider>
    );
};

export default AppContext;


